using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
namespace DesktopTodo {
 public static class Categories {
  public static string[] Children(State state,string parent){if(state.Subcategories==null)state.Subcategories=new System.Collections.Generic.List<SubcategoryDefinition>();return state.Subcategories.Where(s=>parent==""||s.Category==parent).Select(s=>s.Name).Distinct().OrderBy(s=>s).ToArray();}
  public static void Ensure(State state,string parent,string child){if(!state.Categories.Contains(parent))state.Categories.Add(parent);if(state.Subcategories==null)state.Subcategories=new System.Collections.Generic.List<SubcategoryDefinition>();if(!string.IsNullOrWhiteSpace(child)&&!state.Subcategories.Any(s=>s.Category==parent&&s.Name==child))state.Subcategories.Add(new SubcategoryDefinition{Category=parent,Name=child});}
  public static void Rename(State state,string old,string name){if(string.IsNullOrWhiteSpace(name)||state.Categories.Contains(name))throw new InvalidOperationException("비어 있거나 이미 사용 중인 이름입니다.");int index=state.Categories.IndexOf(old);if(index<0)throw new InvalidOperationException("카테고리를 선택하세요.");state.Categories[index]=name;foreach(var t in state.Tasks.Where(t=>t.Category==old))t.Category=name;foreach(var s in state.Subcategories.Where(s=>s.Category==old))s.Category=name;}
  public static void RenameChild(State state,string parent,string old,string name){if(string.IsNullOrWhiteSpace(name)||state.Subcategories.Any(s=>s.Category==parent&&s.Name==name))throw new InvalidOperationException("비어 있거나 이미 사용 중인 이름입니다.");var child=state.Subcategories.FirstOrDefault(s=>s.Category==parent&&s.Name==old);if(child==null)throw new InvalidOperationException("세부 카테고리를 선택하세요.");child.Name=name;foreach(var t in state.Tasks.Where(t=>t.Category==parent&&t.Subcategory==old))t.Subcategory=name;}
 }
 public class CategoryEditor:Border {
  readonly App app;readonly ComboBox parents,children;readonly TextBox parentName,childName;readonly TextBlock status;readonly Button addParent,renameParent,addChild,renameChild;bool updating;
  public CategoryEditor(App owner,Action close){app=owner;Margin=new Thickness(12);Padding=new Thickness(16);Background=Design.Paper;BorderBrush=UI.Color("#3B4350");BorderThickness=new Thickness(1);CornerRadius=new CornerRadius(16);var root=new DockPanel();Child=root;var heading=new DockPanel{Margin=new Thickness(0,0,0,16)};var done=Design.Button("닫기",close);DockPanel.SetDock(done,Dock.Right);heading.Children.Add(done);heading.Children.Add(Design.Text("카테고리",21));DockPanel.SetDock(heading,Dock.Top);root.Children.Add(heading);status=Design.Text("",11,Design.Muted);DockPanel.SetDock(status,Dock.Bottom);root.Children.Add(status);var content=new StackPanel();root.Children.Add(new ScrollViewer{Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled});
   content.Children.Add(Design.Text("프로젝트를 나누고, 세부 작업을 묶어 보세요.",12,Design.Muted));parents=new ComboBox{Margin=new Thickness(0,14,0,8)};content.Children.Add(parents);parentName=Design.Input();parentName.ToolTip="새 카테고리 또는 변경할 이름";content.Children.Add(parentName);var parentActions=UI.Row();addParent=Design.Button("추가",()=>Act(()=>{string name=parentName.Text.Trim();if(name==""||app.Data.Categories.Contains(name))throw new InvalidOperationException("새 카테고리 이름을 입력하세요.");app.Data.Categories.Add(name);Refresh(name);status.Text="카테고리를 추가했어요.";}));renameParent=Design.Button("이름 변경",()=>Act(()=>{string name=parentName.Text.Trim();Categories.Rename(app.Data,SelectedParent,name);Refresh(name);status.Text="카테고리와 포함된 할 일을 함께 변경했어요.";}));parentActions.Children.Add(addParent);parentActions.Children.Add(renameParent);parentActions.Children.Add(Design.Button("삭제",()=>Act(()=>{string parent=SelectedParent;if(app.Data.Tasks.Any(t=>t.Category==parent))throw new InvalidOperationException("할 일을 다른 카테고리로 옮긴 후 삭제하세요.");app.Data.Categories.Remove(parent);app.Data.Subcategories.RemoveAll(s=>s.Category==parent);Refresh(null);})));content.Children.Add(parentActions);
   var label=Design.Text("세부 카테고리",16);label.Margin=new Thickness(0,24,0,8);content.Children.Add(label);children=new ComboBox{Margin=new Thickness(0,0,0,8)};content.Children.Add(children);childName=Design.Input();childName.ToolTip="선택한 카테고리에 추가할 세부 카테고리 이름";content.Children.Add(childName);var childActions=UI.Row();addChild=Design.Button("추가",()=>Act(()=>{if(SelectedParent==""||string.IsNullOrWhiteSpace(childName.Text))throw new InvalidOperationException("상위 카테고리와 세부 이름을 입력하세요.");Categories.Ensure(app.Data,SelectedParent,childName.Text.Trim());RefreshChildren();status.Text="세부 카테고리를 추가했어요.";}));renameChild=Design.Button("이름 변경",()=>Act(()=>{Categories.RenameChild(app.Data,SelectedParent,children.SelectedItem as string,childName.Text.Trim());RefreshChildren();status.Text="세부 카테고리와 할 일을 함께 변경했어요.";}));childActions.Children.Add(addChild);childActions.Children.Add(renameChild);childActions.Children.Add(Design.Button("삭제",()=>Act(()=>{string child=children.SelectedItem as string;if(child==null)return;if(app.Data.Tasks.Any(t=>t.Category==SelectedParent&&t.Subcategory==child))throw new InvalidOperationException("해당 할 일의 세부 분류를 먼저 변경하세요.");app.Data.Subcategories.RemoveAll(s=>s.Category==SelectedParent&&s.Name==child);RefreshChildren();})));content.Children.Add(childActions);
   parents.SelectionChanged+=(o,e)=>{if(updating)return;parentName.Text=SelectedParent;RefreshChildren();};children.SelectionChanged+=(o,e)=>{childName.Text=children.SelectedItem as string??"";};Refresh(app.Data.Categories.FirstOrDefault());
  }
  string SelectedParent {get{return parents.SelectedItem as string??"";}}
  void Act(Action action){try{action();app.Commit();}catch(Exception e){status.Text=e.Message;}}
  void Refresh(string selected){updating=true;parents.ItemsSource=app.Data.Categories.ToList();parents.SelectedItem=selected??app.Data.Categories.FirstOrDefault();parentName.Text=SelectedParent;updating=false;if(children!=null)RefreshChildren();}
  void RefreshChildren(){children.ItemsSource=Categories.Children(app.Data,SelectedParent);children.SelectedIndex=children.Items.Count>0?0:-1;childName.Text=children.SelectedItem as string??"";}
  internal void Verify(){parentName.Text="테스트 프로젝트";addParent.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(!app.Data.Categories.Contains("테스트 프로젝트"))throw new Exception("Inline category creation");parentName.Text="테스트 프로젝트 수정";renameParent.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));childName.Text="자료";addChild.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(!Categories.Children(app.Data,SelectedParent).Contains("자료"))throw new Exception("Subcategory creation");children.SelectedItem="자료";childName.Text="자료 정리";renameChild.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(!Categories.Children(app.Data,SelectedParent).Contains("자료 정리"))throw new Exception("Subcategory rename");}
 }
 public partial class Dashboard {
  CategoryEditor categoryEditor;
  public void ShowCategories(){if(inlineEditor!=null||categoryEditor!=null)return;categoryEditor=new CategoryEditor(app,()=>{chrome.Children.Remove(categoryEditor);categoryEditor=null;Render();});chrome.Children.Add(categoryEditor);ApplyCommandSizes();}
  public void OpenTask(Todo task=null,DateTime? date=null){ShowInline(task,date);}
  internal void VerifyCategoryFlow(){foreach(var q in new[]{0,1,2,3}){ShowInline(null,null,q);inlineEditor.Verify(new[]{"캡스톤 중간 발표","졸업 프로젝트 설계","과제 자료 전달","자료 폴더 정리"}[q]);}ShowCategories();categoryEditor.Verify();chrome.Children.Remove(categoryEditor);categoryEditor=null;}
 }
}
